import React from "react";
import GlowCursor from "../Designed component/GlowCursor";
export default function ProfessionalExperience() {
    return (
        <div className="bg-neutral-950 px-4 py-24">
            <div className="max-w-6xl mx-auto">
                <div style={{ position: 'relative', width: '100%', height: '500px', background: '#050610' }}>
                    <GlowCursor
                        color="#67E8F9"
                        secondaryColor="#A78BFA"
                        trailLength={40}
                        trailWidth={8}
                        trailTaper={0.8}
                        followSpeed={0.16}
                        glowIntensity={1.9}
                        glowSpread={1.2}
                        hotspot={0.65}
                        brightness={1.25}
                        opacity={1}
                        pulseSpeed={1.1}
                        noiseStrength={0.035}
                        idleFade
                        idleTimeout={700}
                        fadeDuration={900}
                        blendMode="screen"
                    >
                    hello john
                    </GlowCursor>
                </div>
            </div>
        </div>

    )
}
